INSERT INTO `catatan_kedisiplinan` (`id_catatan`, `id_siswa`, `id_guru`, `id_kelas`, `id_tahun_ajaran`, `tanggal`, `jenis_pelanggaran`, `catatan`, `dibuat_pada`, `diubah_pada`) VALUES
(1, 68, 5, 4, 1, '2025-07-14', 'Tidak mengikuti piket', 'Farhan tidak melaksanakan tugas piket kelas pada jadwalnya. Diminta mengganti pada hari berikutnya.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(2, 75, 4, 3, 1, '2025-07-18', 'Tidak membawa perlengkapan belajar', 'Indah tidak membawa buku tulis dan alat tulis. Diberi pinjaman dan orang tua diberi tahu.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(3, 72, 4, 3, 1, '2025-08-05', 'Terlambat masuk sekolah', 'Nayla datang terlambat sekitar 15 menit tanpa keterangan. Sudah diingatkan agar berangkat lebih pagi.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(4, 12, 11, 7, 1, '2025-08-14', 'Tidak mengikuti piket', 'Lutfi tidak melaksanakan tugas piket kelas pada jadwalnya. Diminta mengganti pada hari berikutnya.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(5, 59, 5, 4, 1, '2025-09-11', 'Terlambat masuk sekolah', 'Elsa datang terlambat sekitar 10 menit tanpa keterangan. Sudah diingatkan agar berangkat lebih pagi.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(6, 21, 7, 6, 1, '2025-09-23', 'Membawa ponsel tanpa izin', 'Taufik membawa ponsel ke sekolah tanpa izin. Ponsel disimpan Guru dan diambil oleh wali murid.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(7, 41, 6, 5, 1, '2025-09-29', 'Terlambat masuk sekolah', 'Zidan datang terlambat sekitar 30 menit tanpa keterangan. Sudah diingatkan agar berangkat lebih pagi.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(8, 87, 2, 1, 1, '2025-10-02', 'Tidak membawa perlengkapan belajar', 'Indah tidak membawa buku tulis dan alat tulis. Diberi pinjaman dan orang tua diberi tahu.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(9, 16, 11, 7, 1, '2025-10-09', 'Tidak mengerjakan PR', 'Reza tidak mengerjakan PR sebanyak dua kali berturut-turut. Dilakukan pembinaan dan dijadwalkan pendampingan belajar.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(10, 11, 11, 7, 1, '2025-10-11', 'Berbicara kasar', 'Bima berkata kasar kepada teman saat jam istirahat. Sudah dipertemukan dan saling meminta maaf.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(11, 25, 7, 6, 1, '2025-11-25', 'Terlambat masuk sekolah', 'Naufal datang terlambat sekitar 20 menit tanpa keterangan. Sudah diingatkan agar berangkat lebih pagi.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
(12, 75, 4, 3, 1, '2025-12-05', 'Terlambat masuk sekolah', 'Indah datang terlambat sekitar 20 menit tanpa keterangan. Sudah diingatkan agar berangkat lebih pagi.', '2026-10-12 04:41:30', '2026-10-12 04:41:30'),
