INSERT INTO `ekstrakurikuler` (`id_ekskul`, `nama_ekskul`, `deskripsi`, `ikon`) VALUES
(1, 'Pramuka', 'Kegiatan kepramukaan wajib bagi siswa kelas 3-6: baris-berbaris, tali-temali, sandi, dan perkemahan Sabtu-Minggu (Persami).', 'assets/img/ekstrakurikuler/pramuka-2.jpg'),
(2, 'Tari', 'Latihan tari daerah dan tari kreasi untuk penampilan pada acara sekolah dan lomba tingkat kecamatan/kabupaten.', 'assets/img/ekstrakurikuler/tari-1.jpg'),
(5, 'Hadrah', 'Pembiasaan membaca dan menghafal juz 30 bagi siswa kelas 1-6 secara bertahap.', 'uploads/ikon/tahfidz.svg');
INSERT INTO `event_sekolah` (`id_event`, `nama_event`, `kategori`, `tanggal`, `deskripsi`, `banner`, `status_tampil`) VALUES
(1, 'Lomba Peringatan HUT RI ke-81', 'event', '2026-08-15', 'Rangkaian lomba antar-kelas menyambut HUT Kemerdekaan RI: balap karung, tarik tambang, lomba makan kerupuk, dan estafet kelereng. Seluruh siswa dan wali murid ikut memeriahkan.', 'uploads/event/hut-ri-81.jpg', 1),
(2, 'Juara 1 Lomba Cerdas Cermat Tingkat Kecamatan', 'prestasi', '2026-09-12', 'Tim cerdas cermat kelas 5 dan 6 meraih juara 1 pada lomba cerdas cermat antar-SD tingkat kecamatan dan berhak maju ke tingkat kabupaten.', 'uploads/event/cerdas-cermat-2026.jpg', 1),
(3, 'Jumat Bersih Lingkungan Sekolah', 'kegiatan', '2026-08-07', 'Kegiatan rutin gotong royong membersihkan halaman, selokan, dan taman sekolah bersama seluruh siswa dan dewan guru.', 'uploads/event/jumat-bersih.jpg', 1),
(4, 'Pemeriksaan Kesehatan Siswa bersama Puskesmas', 'kolaborasi', '2026-09-26', 'Kolaborasi dengan Puskesmas setempat: pemeriksaan tinggi/berat badan, penglihatan, kesehatan gigi, dan pemberian tablet tambah darah untuk siswa putri.', 'uploads/event/pemeriksaan-kesehatan.jpg', 1),
(5, 'Persami Pramuka Penggalang', 'kegiatan', '2026-09-19', 'Perkemahan Sabtu-Minggu di halaman sekolah diikuti siswa kelas 4-6: upacara pembukaan, api unggun, penjelajahan, dan lomba tali-temali.', 'uploads/event/persami.jpg', 1),
(6, 'Juara 2 Lomba Tari Kreasi Tingkat Kabupaten', 'prestasi', '2026-05-23', 'Tim Tari Tradisional SDN Kedungsari Satu meraih juara 2 pada festival tari kreasi anak tingkat kabupaten.', 'uploads/event/tari-kabupaten.jpg', 1),
(7, 'Wisuda dan Pelepasan Siswa Kelas 6', 'event', '2026-06-20', 'Acara pelepasan 16 lulusan tahun ajaran 2025/2026 yang dihadiri wali murid, komite sekolah, dan perwakilan desa.', 'uploads/event/wisuda-2026.jpg', 1),
(8, 'Sosialisasi dan Pendaftaran PPDB 2026/2027', 'event', '2026-06-08', 'Sosialisasi alur pendaftaran peserta didik baru melalui formulir daring serta verifikasi berkas di sekolah.', 'uploads/event/ppdb-2026.jpg', 1),
(9, 'Mobil Perpustakaan Keliling', 'kolaborasi', '2026-08-28', 'Kolaborasi dengan Dinas Arsip dan Perpustakaan: siswa meminjam dan membaca buku cerita anak dari mobil perpustakaan keliling.', 'uploads/event/perpus-keliling.jpg', 1),
(10, 'Kunjungan Edukasi Kelas 4 dan 5 ke Museum', 'kegiatan', '2026-09-18', 'Siswa kelas 4 dan 5 mengunjungi museum untuk belajar sejarah dan budaya lokal sebagai bagian dari pembelajaran IPAS.', 'uploads/event/kunjungan-museum.jpg', 1),
(11, 'Class Meet', 'event', '2026-10-17', NULL, 'assets/img/event/class-meet-1.jpg', 1),
(12, 'Peringatan Hari Santri Nasional', 'event', '2026-10-22', 'Upacara dan lomba pidato serta kaligrafi dalam rangka Hari Santri Nasional.', 'assets/img/event/peringatan-hari-santri-nasional-8.jpg', 1),
(13, 'Kerja Bakti', 'kegiatan', '2026-12-19', 'Pentas seni siswa (tari, drumband, paduan suara) dilanjutkan pembagian rapor semester ganjil kepada wali murid.', 'assets/img/event/kerja-bakti-1.jpg', 1),
(14, 'Rapat Wali Murid Semester Ganjil', 'kegiatan', NULL, 'Draf agenda rapat wali murid; tanggal dan materi belum ditetapkan.', NULL, 0),
(15, 'Juara 3 Lomba Futsal Antar-SD se-Kecamatan', 'prestasi', '2026-02-07', 'Tim futsal putra kelas 5 dan 6 meraih juara 3 pada turnamen futsal antar-SD se-kecamatan.', 'uploads/event/futsal-juara3.jpg', 1);
