(1, 'senin', 'Senin Disiplin', 'Upacara bendera dan pemeriksaan kerapian seragam untuk membiasakan kedisiplinan.', 'assets/img/program-pembiasaan/senin-disiplin-1.jpg'),
(2, 'selasa', 'Selasa Bugar', 'Senam pagi dan aktivitas jasmani bersama untuk menjaga kebugaran siswa.', 'uploads/ikon/selasa-bugar.svg'),
(3, 'rabu', 'Rabu Religi', 'Doa bersama, pembiasaan membaca Al-Qur\'an dan Asmaul Husna, serta kegiatan keagamaan.', 'uploads/ikon/rabu-religi.svg'),
(4, 'kamis', 'Kamis Berbudaya', 'Berbahasa Jawa, mengenakan busana daerah, dan mengenal seni budaya lokal.', 'uploads/ikon/kamis-berbudaya.svg'),
(5, 'jumat', 'Jumat Ikhlas', 'Jumat bersih, gotong royong, dan berbagi dengan ikhlas.', 'uploads/ikon/jumat-ikhlas.svg'),
(6, 'sabtu', 'Sabtu Ceria', 'Kegiatan ekstrakurikuler dan permainan edukatif yang menyenangkan.', 'uploads/ikon/sabtu-ceria.svg');
